def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after +)
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split core version and pre-release (after -)
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            prerelease_parsed = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))  # 0 = numeric
                else:
                    prerelease_parsed.append((1, identifier))  # 1 = string
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def compare_key(v):
        major, minor, patch, prerelease_parsed = parse_version(v)

        # For sorting: versions without pre-release come after those with pre-release
        # So we use None > [] approach: we want pre-release (not None) to come first
        # In tuples, None sorts after numbers, so we invert by using a flag
        if prerelease_parsed is None:
            prerelease_key = (1,)  # No pre-release comes after
        else:
            prerelease_key = (0, tuple(prerelease_parsed))  # Pre-release comes first

        return (major, minor, patch, prerelease_key)

    # Stable sort to preserve input order for equal precedence
    indexed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    def sort_key(item):
        parsed, original_index, version_str = item
        major, minor, patch, prerelease_parsed = parsed

        if prerelease_parsed is None:
            prerelease_key = (1,)
        else:
            prerelease_key = (0, tuple(prerelease_parsed))

        return (major, minor, patch, prerelease_key, original_index)

    sorted_items = sorted(indexed, key=sort_key)
    return [item[2] for item in sorted_items]

